import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"FAQ and troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),s={name:"guide/faq.md"};function r(i,e,d,l,c,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="faq-and-troubleshooting" tabindex="-1">FAQ and troubleshooting <a class="header-anchor" href="#faq-and-troubleshooting" aria-label="Permalink to &quot;FAQ and troubleshooting&quot;">​</a></h1><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p><strong>The dashboard says “setup issues”.</strong> Click the pill: each failed check shows its fix. Most often ffmpeg is missing (Windows: <code>winget install Gyan.FFmpeg</code>, macOS: <code>brew install ffmpeg</code>, Linux: your package manager). Then restart <code>start.bat</code> / <code>start.sh</code>.</p><p><strong>“Cannot launch Chromium”.</strong> Run <code>reelforge doctor --fix</code>. On Linux, also run the installer again and accept the system libraries prompt.</p><p><strong>“ffmpeg not found” although I installed it (Windows).</strong> Close every terminal and <code>start.bat</code>, then reopen: Windows only picks up the new PATH in new windows.</p><p>More setup fixes are in <a href="./installation.html#troubleshooting">Installation</a>.</p><h2 id="episodes" tabindex="-1">Episodes <a class="header-anchor" href="#episodes" aria-label="Permalink to &quot;Episodes&quot;">​</a></h2><p><strong>A word reference fails: <code>Word &quot;x&quot; not found in line l7</code>.</strong> The error shows the closest word in that line. Words are matched without punctuation and diacritics. For a word containing an apostrophe use double quotes: <code>l7:&quot;Conway&#39;s&quot;</code>. You can also use the word index: <code>l7.3</code> (4th word).</p><p><strong>The caption wraps over three lines (V-10).</strong> Add <code>break: [&quot;word&quot;]</code> to the script line to split the caption before that word, or lower <code>captions.max_chars</code> in the theme.</p><p><strong>Text overflows its box (V-9).</strong> Shorten the text, lower <code>fontSize</code>, or enlarge <code>place.w/h</code>. Titles, quotes and stamps shrink automatically to fit.</p><p><strong>An element sits under the TikTok buttons (V-7).</strong> Press <strong>Z</strong> in the editor to show the safe zones, and keep content out of the red areas. In the lower part of the stage keep <code>x + w ≤ 920</code>.</p><p><strong>Two elements overlap (V-8).</strong> Give the first one an <code>exit</code> before the second enters, move one of them, or put badges and stamps on <code>layer: overlay</code>.</p><p><strong>A line is “spoken too fast” (V-14).</strong> It has more than about 3.5 words per second. Split it into two lines or shorten it.</p><h2 id="fonts-languages-and-formats" tabindex="-1">Fonts, languages and formats <a class="header-anchor" href="#fonts-languages-and-formats" aria-label="Permalink to &quot;Fonts, languages and formats&quot;">​</a></h2><p><strong>Can I use my own fonts?</strong> Themes can use any bundled family (Space Grotesk, Inter, Manrope, Playfair Display, JetBrains Mono, Cairo, Noto Kufi Arabic, Noto Naskh Arabic, Readex Pro). Fonts are bundled so renders never depend on the machine; other fonts are not supported yet.</p><p><strong>Which languages are supported?</strong> English and Arabic captions, including Arabic sentences with English terms.</p><p><strong>Can I make square or landscape videos?</strong> Not in 1.0: ReelForge renders 9:16 vertical video only (ADR-016). Square, portrait and landscape are on the roadmap.</p><h2 id="offline-use-servers-and-ai" tabindex="-1">Offline use, servers and AI <a class="header-anchor" href="#offline-use-servers-and-ai" aria-label="Permalink to &quot;Offline use, servers and AI&quot;">​</a></h2><p><strong>Does ReelForge need the internet?</strong> Only during installation (dependencies, Chromium, ffmpeg) and for the one-time download of the optional speech models. Creating, editing and rendering are fully offline. If you use an AI assistant, the assistant itself needs its own connection and account; ReelForge&#39;s MCP server stays local.</p><p><strong>Can I render on a server or in CI?</strong> Yes: everything is available from the command line (<code>--json</code> gives machine-readable output) and works headless on Linux.</p><p><strong>Does ReelForge send my files anywhere?</strong> No. The servers bind to <code>127.0.0.1</code> by default and the render engine blocks network access. An AI client only sees what it reads through the tools.</p><h2 id="rights-and-files" tabindex="-1">Rights and files <a class="header-anchor" href="#rights-and-files" aria-label="Permalink to &quot;Rights and files&quot;">​</a></h2><p><strong>Can I sell the videos I make?</strong> Yes. The videos are yours, including for clients and monetized channels. See <a href="./license.html">License</a>.</p><p><strong>Where are my files?</strong> Each episode is a folder in <code>episodes/</code> containing <code>episode.yaml</code>, <code>voice.wav</code>, <code>cues.json</code>, <code>assets/</code> and <code>out/</code>. Back it up like any other folder (Git works well).</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Ask in <a href="https://github.com/TerminalDZ/vidcreat/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> or open an <a href="https://github.com/TerminalDZ/vidcreat/issues" target="_blank" rel="noreferrer">issue</a>. Include your operating system, the output of <code>reelforge doctor --json</code> and the command you ran with <code>--verbose</code>.</p>',26)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
